import{_ as a,o as n,c as o,aa as t}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/cs/diary/m_off_zaznam.jpg",m=JSON.parse('{"title":"Práce bez signálu","description":"","frontmatter":{"title":"Práce bez signálu","wiki":"cs:diary:m_offline"},"headers":[],"relativePath":"diary/m_offline.md","filePath":"diary/m_offline.md","lastUpdated":1794209661000}'),r={name:"diary/m_offline.md"};function l(s,e,p,d,u,v){return n(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="prace-bez-signalu" tabindex="-1">Práce bez signálu <a class="header-anchor" href="#prace-bez-signalu" aria-label="Permalink to &quot;Práce bez signálu&quot;">​</a></h1><p>Když na stavbě není signál nebo je slabý, pracujte v mobilní aplikaci v offline režimu. Záznamy v deníku i úkoly se ukládají do telefonu a na server se odešlou při synchronizaci, až budete zase připojeni.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/mobilni-aplikace-denik">Psát deník v mobilu</a> v Akademii.</p><h2 id="co-jde-offline" tabindex="-1">Co jde offline <a class="header-anchor" href="#co-jde-offline" aria-label="Permalink to &quot;Co jde offline&quot;">​</a></h2><p><strong>Ve stavebním deníku</strong> můžete zakládat nové záznamy a v omezené míře upravovat existující.</p><p><strong>V úkolech</strong> můžete zakládat nové úkoly, upravovat úkoly, které jste už dříve otevřeli, a přidávat k nim vyjádření.</p><p>Bez připojení nefunguje například:</p><ul><li>načtení počasí,</li><li>návrh záznamu pomocí AI,</li><li>změna stavu dne,</li><li>reakce na záznam,</li><li>podepisování záznamů a dnů.</li></ul><h2 id="zapnout-a-vypnout-offline-rezim" tabindex="-1">Zapnout a vypnout offline režim <a class="header-anchor" href="#zapnout-a-vypnout-offline-rezim" aria-label="Permalink to &quot;Zapnout a vypnout offline režim&quot;">​</a></h2><p>Pokud aplikaci spustíte bez připojení, přepne se do offline režimu sama. Ručně ho zapnete v <a href="/buildary-help-preview/diary/m_project_list">menu aplikace</a> → <strong>Nastavení</strong> → <strong>Pracovat offline</strong>. Zpět se přepnete na stejném místě volbou <strong>Pracovat online</strong>.</p><p>Ruční offline režim se hodí i tam, kde je signál, ale práce online je pomalá, nebo když chcete šetřit data.</p><h2 id="jak-poznate-ze-jste-offline" tabindex="-1">Jak poznáte, že jste offline <a class="header-anchor" href="#jak-poznate-ze-jste-offline" aria-label="Permalink to &quot;Jak poznáte, že jste offline&quot;">​</a></h2><ul><li>Záhlaví aplikace je červené.</li><li>Záznamy a úkoly, které jsou zatím jen v telefonu a ne na serveru, mají vpravo ikonu přeškrtnuté Wi-Fi. Po synchronizaci ikona zmizí.</li></ul><figure class="shot" style="--w:260px;"><img src="'+i+'" alt="Deník v offline režimu: červené záhlaví a záznamy s ikonou přeškrtnuté Wi-Fi" loading="lazy"></figure><p>Dokud data nesynchronizujete, ostatní je nevidí – záznamy a úkoly jsou jen ve vašem telefonu.</p><h2 id="synchronizovat-data" tabindex="-1">Synchronizovat data <a class="header-anchor" href="#synchronizovat-data" aria-label="Permalink to &quot;Synchronizovat data&quot;">​</a></h2><p>Připojte se k internetu (Wi-Fi nebo mobilní data) a otevřete aplikaci. Pokud jste offline režim zapnuli ručně, přepněte se volbou <strong>Pracovat online</strong>. Synchronizaci pak spustíte novým načtením dat:</p><ul><li><strong>Jedna obrazovka</strong> – otevřete obrazovku, na které jste data měnili (třeba jednu sekci deníku), a potáhněte prstem po displeji shora dolů.</li><li><strong>Celý deník</strong> – otevřete deník znovu ze <strong>Seznamu deníků</strong>.</li><li><strong>Celá stavba</strong> – v <strong>Seznamu staveb</strong> otevřete stavbu. Synchronizují se všechny její deníky i úkoly – nejrychlejší cesta, když máte offline data ve více denících.</li><li><strong>Více staveb</strong> – v <strong>Seznamu staveb</strong> podržte prst na stavbě, označte další stavby a hromadnou synchronizaci spusťte volbou v záhlaví.</li></ul><p>Synchronizace odešle vaše změny na server a do telefonu přenese změny, které mezitím udělali ostatní.</p><div class="warning custom-block"><p class="custom-block-title">Při konfliktu vyhrává server</p><p>Pokud někdo mezitím změnil stejná data na serveru, platí verze ze serveru. Konfliktní změny z telefonu se neuloží. Proto synchronizujte co nejčastěji, alespoň jednou denně.</p></div><h2 id="pripravit-stavbu-pred-praci-offline" tabindex="-1">Připravit stavbu před prací offline <a class="header-anchor" href="#pripravit-stavbu-pred-praci-offline" aria-label="Permalink to &quot;Připravit stavbu před prací offline&quot;">​</a></h2><p>Na nové stavbě si nejdřív připravte <a href="/buildary-help-preview/diary/codelists">číselníky</a> a nahrajte <a href="/buildary-help-preview/diary/projectparts">výkresy</a>. Pak stavbu v telefonu otevřete při dobrém připojení, aby se všechno stáhlo. Nejdéle trvá stažení výkresů; další synchronizace už přenášejí jen změny a jsou rychlé.</p>',22)])])}const f=a(r,[["render",l]]);export{m as __pageData,f as default};
